/// 🧭️ A caller-bound registration search with one retained source and one bounded comparison page.
pub struct OriginalWireAdmission{binding:OriginalSourceBinding,decoder:(semio_framework_value::retained_clone::NativeAllocationIdentity,u64),loan:ManuallyDrop<Option<semio_framework_job::OriginalCallerSourceLoan>>,returning:bool,key:ManuallyDrop<Option<ToolFactoryKey>>,schema:ManuallyDrop<Option<String>>,raw:usize,bus:ManuallyDrop<Option<ActionBus>>,catalogue_len:usize,row:usize,field:u8,offset:usize,matched:bool,closing:bool,retirement:RetainedCloneClose}
